/**
 * `.xz` fixtures for the decoder tests. Tests cannot shell out to `xz`
 * (guideline 5: no ambient tools), so the archives were produced once with
 * XZ Utils 5.4 and embedded here as base64. The tarballs inside were built
 * with this package's own `tar()`; the stress payload is regenerated by
 * {@link stressPayload}, so a test compares the decoder's output byte for
 * byte without storing the expectation twice.
 *
 * @module
 */

/** Decode a base64 fixture to bytes. */
export function fixture(base64: string): Uint8Array {
  return Uint8Array.from(
    atob(base64.replace(/\s+/g, "")),
    (c) => c.charCodeAt(0),
  );
}

/**
 * A payload designed to walk every LZMA path: word salad from a small
 * vocabulary (short matches at many distances, literals after matches), a
 * verbatim repeat of its opening (one long-distance match with long lengths),
 * and a 4 KiB run of pseudo-random bytes. Compressed with `--block-size=4096 -T2`
 * (`STRESS_XZ`: threaded mode also records block sizes in the headers), that run fills a block of its own, which xz stores as an
 * uncompressed LZMA2 chunk.
 */
export function stressPayload(): Uint8Array {
  const words = [
    "flutter",
    "dart",
    "zig",
    "build",
    "target",
    "tool",
    "install",
    "tree",
    "archive",
    "xz",
    "lzma",
    "checksum",
    "symlink",
    "strip",
    "bins",
    "deno",
  ];
  let seed = 0x2545f491;
  const next = () => {
    seed = (Math.imul(seed, 1103515245) + 12345) >>> 0;
    return seed >>> 8;
  };
  const parts: string[] = [];
  for (let i = 0; i < 4000; i++) {
    const n = next();
    parts.push(words[n % words.length]);
    parts.push(n % 11 === 0 ? ".\n" : n % 7 === 0 ? `${n % 1000}` : " ");
  }
  const text = new TextEncoder().encode(parts.join(""));
  const noise = Uint8Array.from({ length: 4096 }, () => next() & 0xff);
  const out = new Uint8Array(4096 + noise.length + text.length + 4096);
  out.set(text.subarray(0, 4096), 0);
  out.set(noise, 4096);
  out.set(text, 4096 + noise.length);
  out.set(text.subarray(0, 4096), 4096 + noise.length + text.length);
  return out;
}

